// src/repositories/profiles.ts
async function findProfile(userId) {
  const rows = await sql`
    SELECT id, email, full_name, age, gender, state, activity_level, diet_habit,
           smoking, height_cm::float8 AS height_cm, weight_kg::float8 AS weight_kg,
           bmi::float8 AS bmi, alcohol, sleep_hours::float8 AS sleep_hours,
           high_blood_pressure, diabetes, onboarding_complete, locale, active_action_ids
    FROM profiles
    WHERE id = ${userId}
  `;
  return rows[0] ?? null;
}
async function createProfile(userId, email, fullName) {
  const row = await sqlOne`
    INSERT INTO profiles (id, email, full_name)
    VALUES (${userId}, ${email}, ${fullName})
    ON CONFLICT (id) DO UPDATE SET
      email     = EXCLUDED.email,
      full_name = EXCLUDED.full_name
    RETURNING id, email, full_name, age, gender, state, activity_level, diet_habit,
              smoking, height_cm::float8 AS height_cm, weight_kg::float8 AS weight_kg,
              bmi::float8 AS bmi, alcohol, sleep_hours::float8 AS sleep_hours,
              high_blood_pressure, diabetes, onboarding_complete, locale, active_action_ids
  `;
  if (row === null) throw new Error("Failed to create profile");
  return row;
}
async function upsertProfile(userId, input) {
  const row = await sqlOne`
    INSERT INTO profiles (
      id, email, full_name, age, gender, state, activity_level, diet_habit,
      smoking, height_cm, weight_kg, bmi, alcohol, sleep_hours,
      high_blood_pressure, diabetes, onboarding_complete, locale, active_action_ids
    ) VALUES (
      ${userId}, ${input.email}, ${input.fullName}, ${input.age}, ${input.gender},
      ${input.state}, ${input.activityLevel}, ${input.dietHabit}, ${input.smoking},
      ${input.heightCm}, ${input.weightKg}, ${input.bmi}, ${input.alcohol}, ${input.sleepHours},
      ${input.highBloodPressure}, ${input.diabetes}, ${input.onboardingComplete},
      ${input.locale}, ${input.activeActionIds}
    )
    ON CONFLICT (id) DO UPDATE SET
      email               = EXCLUDED.email,
      full_name           = EXCLUDED.full_name,
      age                 = EXCLUDED.age,
      gender              = EXCLUDED.gender,
      state               = EXCLUDED.state,
      activity_level      = EXCLUDED.activity_level,
      diet_habit          = EXCLUDED.diet_habit,
      smoking             = EXCLUDED.smoking,
      height_cm           = EXCLUDED.height_cm,
      weight_kg           = EXCLUDED.weight_kg,
      bmi                 = EXCLUDED.bmi,
      alcohol             = EXCLUDED.alcohol,
      sleep_hours         = EXCLUDED.sleep_hours,
      high_blood_pressure = EXCLUDED.high_blood_pressure,
      diabetes            = EXCLUDED.diabetes,
      onboarding_complete = EXCLUDED.onboarding_complete,
      locale              = EXCLUDED.locale,
      active_action_ids   = EXCLUDED.active_action_ids
    RETURNING id, email, full_name, age, gender, state, activity_level, diet_habit,
              smoking, height_cm::float8 AS height_cm, weight_kg::float8 AS weight_kg,
              bmi::float8 AS bmi, alcohol, sleep_hours::float8 AS sleep_hours,
              high_blood_pressure, diabetes, onboarding_complete, locale, active_action_ids
  `;
  if (row === null) throw new Error("Failed to save profile");
  return row;
}

// src/repositories/users.ts
async function findUserByEmail(email) {
  const rows = await sql`
    SELECT id, email, password_hash
    FROM users
    WHERE lower(email) = lower(${email})
  `;
  return rows[0] ?? null;
}
async function findUserById(id) {
  const rows = await sql`SELECT id, email FROM users WHERE id = ${id}`;
  return rows[0] ?? null;
}
async function createUser(email, passwordHash) {
  return sqlOne`
    INSERT INTO users (email, password_hash)
    VALUES (${email}, ${passwordHash})
    ON CONFLICT ((lower(email))) DO NOTHING
    RETURNING id, email
  `;
}
async function createUserWithProfile(email, passwordHash, fullName) {
  const row = await sqlOne`
    WITH inserted AS (
      INSERT INTO users (email, password_hash)
      VALUES (${email}, ${passwordHash})
      ON CONFLICT ((lower(email))) DO NOTHING
      RETURNING id, email
    ),
    profile AS (
      INSERT INTO profiles (id, email, full_name)
      SELECT id, email, ${fullName} FROM inserted
      RETURNING id, email, full_name, age, gender, state, activity_level, diet_habit,
                smoking, height_cm::float8 AS height_cm, weight_kg::float8 AS weight_kg,
                bmi::float8 AS bmi, alcohol, sleep_hours::float8 AS sleep_hours,
                high_blood_pressure, diabetes, onboarding_complete, locale, active_action_ids
    )
    SELECT
      inserted.id AS user_id,
      inserted.email AS user_email,
      profile.id, profile.email, profile.full_name, profile.age, profile.gender, profile.state,
      profile.activity_level, profile.diet_habit, profile.smoking,
      profile.height_cm, profile.weight_kg, profile.bmi, profile.alcohol, profile.sleep_hours,
      profile.high_blood_pressure, profile.diabetes, profile.onboarding_complete,
      profile.locale, profile.active_action_ids
    FROM inserted
    JOIN profile ON profile.id = inserted.id
  `;
  if (row === null) return null;
  const {
    user_id: userId,
    user_email: userEmail,
    ...profile
  } = row;
  return {
    user: { id: userId, email: userEmail },
    profile
  };
}

